#[test]
fn bond_dsc_matches_excel() {
    let mut bad = Vec::new();
    for (cell, name, args, excel) in rows() {
        match ev(name, args) {
            Value::Number(x) if (x - excel).abs() <= 1e-9 * excel.abs().max(1.0) => {}
            other => bad.push(format!("{cell} {name}: got {other:?}, Excel {excel}")),
        }
    }
    assert!(bad.is_empty(), "{} rows differ from Excel:\n{}", bad.len(), bad.join("\n"));
}
